import React, { useState, useEffect } from 'react';

interface FloatingTooltipProps {
  mousePosition: { x: number; y: number };
}

interface ClassInfo {
  id: string;
  title: string;
  description: string;
  context: string;
}

const FloatingTooltip: React.FC<FloatingTooltipProps> = ({ mousePosition }) => {
  const [tooltipContent, setTooltipContent] = useState<ClassInfo | null>(null);

  useEffect(() => {
    const handleMouseOver = (event: Event) => {
      const target = event.target as HTMLElement;
      // Find the closest parent element with data-class-id, or use the target itself
      const elementWithClass = target.closest('[data-class-id]') as HTMLElement;
      const classId = elementWithClass?.getAttribute('data-class-id');
      
      if (classId) {
        // Get class info from the predefined classes
        const classInfo = getClassInfo(classId);
        if (classInfo) {
          setTooltipContent(classInfo);
        }
      }
    };

    const handleMouseOut = () => {
      setTooltipContent(null);
    };

    const handleMouseMove = (event: MouseEvent) => {
      const target = event.target as HTMLElement;
      // Check if mouse is over simulation controls (but not the tooltip itself)
      const isOverSimulationControls = target.closest('.simulation-controls') !== null;
      const isOverTooltip = target.closest('[data-tooltip="true"]') !== null;
      
      if (isOverSimulationControls && !isOverTooltip) {
        console.log('Hiding tooltip - hovering over simulation controls');
        setTooltipContent(null);
      }
    };

    // Function to add event listeners
    const addEventListeners = () => {
      const elementsWithClasses = document.querySelectorAll('[data-class-id]');
      
      elementsWithClasses.forEach(element => {
        element.addEventListener('mouseover', handleMouseOver);
        element.addEventListener('mouseout', handleMouseOut);
      });
    };

    // Add listeners immediately
    addEventListeners();

    // Also add listeners periodically to catch dynamically created elements
    const interval = setInterval(addEventListeners, 1000);

    // Add global mouse move listener to detect simulation controls
    document.addEventListener('mousemove', handleMouseMove);

    return () => {
      clearInterval(interval);
      const elementsWithClasses = document.querySelectorAll('[data-class-id]');
      elementsWithClasses.forEach(element => {
        element.removeEventListener('mouseover', handleMouseOver);
        element.removeEventListener('mouseout', handleMouseOut);
      });
      document.removeEventListener('mousemove', handleMouseMove);
    };
  }, []);

  // Predefined classes - this should match your class framework
  const getClassInfo = (classId: string): ClassInfo | null => {
    const classes: Record<string, ClassInfo> = {
      'fake-browser-bar': {
        id: 'fake-browser-bar',
        title: 'Fake Browser Bar',
        description: 'A deceptive browser address bar that mimics legitimate browser interfaces to trick users into thinking they are on a real website.',
        context: 'This element is designed to look like a real browser address bar but is actually part of the scareware simulation.'
      },
      'fake-url': {
        id: 'fake-url',
        title: 'Fake URL',
        description: 'A counterfeit URL that appears legitimate to add credibility to the scareware simulation.',
        context: 'This URL is fabricated to make the scareware look like it\'s coming from a legitimate source, even though it doesn\'t actually go anywhere.'
      },
      'malwarebytes-scan': {
        id: 'malwarebytes-scan',
        title: 'Malwarebytes Scan Interface',
        description: 'A realistic simulation of Malwarebytes antivirus software interface used to create false security alerts.',
        context: 'This is part of the scareware simulation to demonstrate how fake security software can appear legitimate.'
      },
      'norton-browser-bar': {
        id: 'norton-browser-bar',
        title: 'Fake Browser Bar',
        description: 'A deceptive browser interface that mimics legitimate browser address bars and navigation elements to trick users.',
        context: 'This element is designed to look like a real browser but is actually part of the scareware simulation to create false legitimacy.'
      },
      'fake-security-indicator': {
        id: 'fake-security-indicator',
        title: 'Fake Security Indicator',
        description: 'A counterfeit security lock icon that appears to indicate a secure connection or protected status.',
        context: 'This lock icon is designed to make users believe they are on a legitimate, secure website.'
      }
    };

    return classes[classId] || null;
  };

  // Calculate smart positioning to keep tooltip on screen
  const calculatePosition = () => {
    const tooltipWidth = 350; // Approximate tooltip width
    const tooltipHeight = 150; // Approximate tooltip height
    const padding = 20; // Padding from screen edges
    
    // Position tooltip in bottom right corner relative to mouse
    let left = mousePosition.x + 20;
    let top = mousePosition.y + 20;
    
    // Check right edge
    if (left + tooltipWidth > window.innerWidth - padding) {
      left = mousePosition.x - tooltipWidth - 20;
    }
    
    // Check left edge
    if (left < padding) {
      left = padding;
    }
    
    // Check bottom edge
    if (top + tooltipHeight > window.innerHeight - padding) {
      top = mousePosition.y - tooltipHeight - 20;
    }
    
    // Check top edge
    if (top < padding) {
      top = padding;
    }
    
    return { left, top };
  };

  const position = calculatePosition();

  // Always show tooltip for debugging
  const displayContent = tooltipContent || {
    id: 'debug',
    title: 'Debug Mode',
    description: 'Tooltip is always visible for debugging. Hover over elements with classes to see their information.',
    context: 'This tooltip will show class information when hovering over elements with data-class-id attributes.'
  };

  return (
    <div
      className="floating-tooltip dark-mode"
      data-tooltip="true"
      style={{
        position: 'fixed',
        top: position.top,
        left: position.left,
        background: 'rgba(45, 45, 45, 0.95)',
        border: '3px solid #007bff',
        borderRadius: '12px',
        padding: '1.5rem',
        zIndex: 99999,
        boxShadow: '0 8px 32px rgba(0,0,0,0.3)',
        backdropFilter: 'blur(10px)',
        minWidth: '300px',
        maxWidth: '400px',
        cursor: 'default',
        userSelect: 'auto',
        transition: 'box-shadow 0.2s',
        pointerEvents: 'auto',
        isolation: 'isolate'
      }}
    >
      <div 
        style={{ 
          textAlign: 'center', 
          marginBottom: '1rem',
          borderBottom: '2px solid #007bff',
          paddingBottom: '0.5rem',
          cursor: 'default',
          userSelect: 'none',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          pointerEvents: 'auto',
          position: 'relative',
          zIndex: 99999
        }}
      >
        <div style={{ flex: 1 }}>
          <h3 style={{ 
            margin: 0, 
            color: '#007bff', 
            fontSize: '1.2rem',
            fontWeight: 'bold',
            pointerEvents: 'none'
          }}>
            {displayContent.title}
          </h3>
        </div>
      </div>

      <div style={{ 
        fontSize: '1rem', 
        color: '#ffffff',
        textAlign: 'left',
        padding: '0.5rem 0'
      }}>
        <p style={{ marginBottom: '1rem', lineHeight: '1.5' }}>
          {displayContent.description}
        </p>
        <p style={{ 
          fontSize: '0.9rem', 
          color: '#b0b0b0',
          fontStyle: 'italic',
          lineHeight: '1.4'
        }}>
          {displayContent.context}
        </p>
      </div>
    </div>
  );
};

export default FloatingTooltip;
